import { useCallback, useRef } from "react";
export const useThrottle = function (callback, delay = 400) {
    const timeoutRef = useRef(undefined);
    const latestValuesRef = useRef(undefined);
    return useCallback((...rest) => {
        if (!timeoutRef.current) {
            timeoutRef.current = setTimeout(() => {
                latestValuesRef.current && callback(...(latestValuesRef.current));
                timeoutRef.current = undefined;
                latestValuesRef.current = undefined;
            }, delay);
        }
        latestValuesRef.current = rest;
        return () => clearTimeout(timeoutRef.current);
    }, [callback, delay]);
};
